using System;using System.Drawing;using System.IO;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmSystemSettings:StyledForm {
 SystemSettingsQuery q=new SystemSettingsQuery();TextBox university=T(),academic=T(),fee=T(),prefix=T(),kname=T(),kphone=T(),wname=T(),wphone=T(),bank=T(),bankname=T(),bankno=T(),branch=T();PictureBox logo=Pic(),campus=Pic(),qr=Pic();string logoPath,campusPath,qrPath;
 static TextBox T(){return new TextBox{Width=300};}static PictureBox Pic(){return new PictureBox{Width=150,Height=110,SizeMode=PictureBoxSizeMode.Zoom,BorderStyle=BorderStyle.FixedSingle,BackColor=Color.White};}public FrmSystemSettings(){Text="System Settings";Size=new Size(1050,720);var tabs=new TabControl{Dock=DockStyle.Fill};tabs.TabPages.Add(Page("University",UniversityPage()));tabs.TabPages.Add(Page("Online Payment",PaymentPage()));tabs.TabPages.Add(Page("Images",ImagesPage()));Controls.Add(tabs);Controls.Add(UiTheme.Heading("System Settings","Changes are stored in the Access database and used by new registrations"));LoadValues();}TabPage Page(string title,Control c){var p=new TabPage(title){BackColor=UiTheme.Pale};p.Controls.Add(c);return p;}FlowLayoutPanel Flow(){return new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(28)};}void Field(Control p,string label,Control c){p.Controls.Add(new Label{Text=label,AutoSize=true,Font=new Font("Segoe UI",9,FontStyle.Bold),Margin=new Padding(3,9,3,2)});p.Controls.Add(c);}Button SaveButton(){var b=new Button{Text="Save Settings",Width=180,Height=42,Margin=new Padding(3,22,3,3)};b.Click+=delegate{Save();};return b;}
 Control UniversityPage(){var p=Flow();p.Controls.Add(new Label{Text="UNIVERSITY INFORMATION",AutoSize=true,Font=new Font("Segoe UI",13,FontStyle.Bold),ForeColor=UiTheme.Navy});Field(p,"University Name",university);Field(p,"Academic Year",academic);Field(p,"Registration Fee (MMK)",fee);Field(p,"Roll Number Prefix",prefix);p.Controls.Add(SaveButton());return p;}Control PaymentPage(){var p=Flow();p.Controls.Add(new Label{Text="KPAY",AutoSize=true,Font=new Font("Segoe UI",12,FontStyle.Bold),ForeColor=UiTheme.Navy});Field(p,"Account Name",kname);Field(p,"Phone Number",kphone);p.Controls.Add(new Label{Text="WAVE PAY",AutoSize=true,Font=new Font("Segoe UI",12,FontStyle.Bold),ForeColor=UiTheme.Navy,Margin=new Padding(3,18,3,3)});Field(p,"Account Name",wname);Field(p,"Phone Number",wphone);p.Controls.Add(new Label{Text="BANKING",AutoSize=true,Font=new Font("Segoe UI",12,FontStyle.Bold),ForeColor=UiTheme.Navy,Margin=new Padding(3,18,3,3)});Field(p,"Bank Name",bank);Field(p,"Account Name",bankname);Field(p,"Account Number",bankno);Field(p,"Branch",branch);p.Controls.Add(SaveButton());return p;}Control ImagesPage(){var p=Flow();p.Controls.Add(ImageRow("University Logo",logo,delegate(string s){logoPath=s;}));p.Controls.Add(ImageRow("University Campus Photo",campus,delegate(string s){campusPath=s;}));p.Controls.Add(ImageRow("Payment QR Code",qr,delegate(string s){qrPath=s;}));p.Controls.Add(SaveButton());return p;}Control ImageRow(string title,PictureBox pic,Action<string> set){var row=new FlowLayoutPanel{Width=850,Height=145};row.Controls.Add(new Label{Text=title,Width=190,Height=110,TextAlign=ContentAlignment.MiddleLeft,Font=new Font("Segoe UI",10,FontStyle.Bold)});row.Controls.Add(pic);var b=new Button{Text="Change Image",Width=140,Height=38,Margin=new Padding(18,35,3,3)};b.Click+=delegate{using(var o=new OpenFileDialog{Filter="Images|*.jpg;*.jpeg;*.png"})if(o.ShowDialog()==DialogResult.OK){if(!FileHelper.Allowed(o.FileName,false)){MessageBox.Show("Select a JPG or PNG image up to 5 MB.");return;}string path=FileHelper.CopyUpload(o.FileName,"Settings");set(path);SetPicture(pic,path);}};row.Controls.Add(b);return row;}
 void LoadValues(){university.Text=q.Get("UniversityName");academic.Text=q.Get("AcademicYear");fee.Text=q.Get("RegistrationFee");prefix.Text=q.Get("RollNumberPrefix");kname.Text=q.Get("KPayAccountName");kphone.Text=q.Get("KPayPhone");wname.Text=q.Get("WaveAccountName");wphone.Text=q.Get("WavePhone");bank.Text=q.Get("BankName");bankname.Text=q.Get("BankAccountName");bankno.Text=q.Get("BankAccountNumber");branch.Text=q.Get("BankBranch");logoPath=q.Get("UniversityLogoPath");campusPath=q.Get("UniversityPhotoPath");qrPath=q.Get("PaymentQRPath");SetPicture(logo,logoPath);SetPicture(campus,campusPath);SetPicture(qr,qrPath);}void SetPicture(PictureBox p,string path){if(!File.Exists(path))return;using(var im=Image.FromFile(path))p.Image=new Bitmap(im);}void Save(){decimal amount;if(string.IsNullOrWhiteSpace(university.Text)||string.IsNullOrWhiteSpace(academic.Text)||!decimal.TryParse(fee.Text,out amount)||amount<0){MessageBox.Show("Enter a university name, academic year, and valid registration fee.");return;}string[,] values={{"UniversityName",university.Text.Trim()},{"AcademicYear",academic.Text.Trim()},{"RegistrationFee",amount.ToString("0.##")},{"RollNumberPrefix",prefix.Text.Trim()},{"KPayAccountName",kname.Text.Trim()},{"KPayPhone",kphone.Text.Trim()},{"WaveAccountName",wname.Text.Trim()},{"WavePhone",wphone.Text.Trim()},{"BankName",bank.Text.Trim()},{"BankAccountName",bankname.Text.Trim()},{"BankAccountNumber",bankno.Text.Trim()},{"BankBranch",branch.Text.Trim()},{"UniversityLogoPath",logoPath??""},{"UniversityPhotoPath",campusPath??""},{"PaymentQRPath",qrPath??""}};for(int i=0;i<values.GetLength(0);i++)q.Save(values[i,0],values[i,1]);MessageBox.Show("Settings saved successfully. New registration forms will use these values.");}
} }
